int process_sysctl_dir_read(struct file *file, struct dir_context *ctx) {
    struct sysctl_dir_header *header;

    header = get_sysctl_dir_header(file);
    if (!header)
        return -ENOENT;

    if (dir_emit_dot(ctx))
        return -EINVAL;

    if (dir_emit_dotdot(ctx))
        return -EINVAL;

    while (header->entries && header->current < header->entry_count) {
        struct sysctl_dir_entry *entry = &header->entries[header->current];
        int ret = scan_sysctl_entry(entry, ctx);
        if (ret)
            return ret;
        header->current++;
    }

    finish_sysctl_dir_header(header);
    return 0;
}

int process_sysctl_dir_read(struct file *file, struct dir_context *ctx) {
    struct sysctl_dir_header *header;

    header = get_sysctl_dir_header(file);
    if (IS_ERR_OR_NULL(header))
        return PTR_ERR(header);

    if (dir_emit_dot(ctx) < 0)
        return -EFAULT;

    if (dir_emit_dotdot(ctx) < 0)
        return -EFAULT;

    while (has_more_entries(header)) {
        struct sysctl_entry *entry = get_next_entry(header);
        if (IS_ERR_OR_NULL(entry))
            return PTR_ERR(entry);

        if (scan_dir_entry(entry, ctx) < 0)
            return -EFAULT;
    }

    finish_sysctl_header(header);
    return 0;
}

#include <linux/sysctl.h>
#include <linux/file.h>

int process_sysctl_dir_request(struct file *file, struct dir_context *ctx) {
    struct ctl_dir *dir;
    int ret;

    dir = (struct ctl_dir *)file->f_path.dentry->d_inode->i_private;
    if (!dir)
        return -EINVAL;

    ret = dir_emit_dot(ctx);
    if (ret < 0)
        return ret;

    ret = dir_emit_dotdot(ctx);
    if (ret < 0)
        return ret;

    ret = ctl_dir_scan(dir, ctx);
    if (ret < 0)
        return ret;

    return 0;
}
